sys_script.script:
(function executeRule(current, previous) {
    try {
        var resp = new sn_aia.AiAgentRuntimeUtil().startAiAgentConversation({
            targetRecordId: current.getUniqueValue(),
            triggerConfigId: ''
        });
        gs.info('[PTAG chaser] conversation start: ' + JSON.stringify(resp));
    } catch (e) {
        gs.warn('[PTAG chaser] failed to start agent conversation: ' + e);
    }
})(current, previous);
